export type FalconThemeId = (typeof FALCON_THEMES)[number]["id"];
const byId = new Map<string, (typeof FALCON_THEMES)[number]>(
  FALCON_THEMES.map((theme) => [theme.id, theme]),
);
export function getFalconTheme(id: unknown) {
  return typeof id === "string" ? byId.get(id) : undefined;
}
